SELECT date('2024-02-29'), time('2024-02-29'), datetime('2024-02-29', 'unixepoch'), julianday('2024-02-29'), strftime('%s', '2024-02-29'), unixepoch('2024-02-29'), timediff('2024-03-01', '2023-01-15');
WITH RECURSIVE f(n, a, b) AS (SELECT 1, 0, 1 UNION ALL SELECT n + 1, b, a + b FROM f WHERE n < 54) SELECT n, a FROM f ORDER BY n DESC LIMIT 5;
WITH RECURSIVE s(x) AS (SELECT 7 UNION ALL SELECT CASE WHEN x % 2 THEN 3 * x + 1 ELSE x / 2 END FROM s WHERE x <> 1) SELECT count(*), max(x), group_concat(x) FROM s;
WITH a(x) AS (VALUES(1),(2),(3)), b(y) AS (SELECT x * x FROM a) SELECT x, y FROM a, b ORDER BY x, y;
